    #[test]
    fn anonymous_decorated_class_reports_exact_grammar_and_missing_name_diagnostics() {
        let source = parsed("class {\n  @x\n  m() {}\n};");
        let file = FileId::new(8_367);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());
        let declaration = source
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::ClassDeclaration).then_some(NodeRef::new(
                    source.arena.id(),
                    file,
                    node,
                ))
            })
            .unwrap();
        let decorator = source
            .arena
            .iter()
            .find_map(|(_, record)| {
                let NodeData::Decorator(decorator) = &record.data else {
                    return None;
                };
                Some(NodeRef::new(source.arena.id(), file, decorator.expression))
            })
            .unwrap();
        let (_, bound) = context.file(file).unwrap();
        let owner = bound.symbol(declaration).unwrap();

        context.check_source_file(file).unwrap();

        let [class, missing] = context.diagnostics().as_slice() else {
            panic!("expected the anonymous class and missing decorator diagnostics")
        };
        assert_eq!(class.node, Some(declaration));
        assert_eq!(class.diagnostic.code(), 1211);
        assert_eq!(
            class.range_override.unwrap().range(),
            TextRange::new(ts_core::TextPos::new(0), ts_core::TextPos::new(5)),
        );
        assert_eq!(missing.node, Some(decorator));
        assert_eq!(missing.diagnostic.code(), 2304);
        assert_eq!(missing.diagnostic.arguments, ["x"]);
        assert!(context.store().declared_type_links(owner).is_none());
        assert!(context.store().value_symbol_links(owner).is_none());

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

    #[test]
    fn recovered_anonymous_modules_check_nested_blocks_and_node_global_names() {
        const SOURCE: &str = concat!(
            "module {\n",
            "  export var foo = 1;\n",
            "  module {\n",
            "    export var bar = 1;\n",
            "  }\n",
            "  var bar = 2;\n",
            "  module {\n",
            "    var x = bar;\n",
            "  }\n",
            "}"
        );
        let source = parse_source_file(SOURCE);
        assert_eq!(
            source
                .diagnostics
                .iter()
                .map(|diagnostic| diagnostic.code)
                .collect::<Vec<_>>(),
            vec![Some(1437), Some(1437), Some(1437)],
        );
        let file = FileId::new(8_391);
        let mut context = context(&[(file, &source)], CanonicalCheckerOptions::default());

        context.check_source_file(file).unwrap();

        let diagnostics = context.diagnostics().as_slice();
        assert_eq!(diagnostics.len(), 3);
        for diagnostic in diagnostics {
            assert_eq!(diagnostic.diagnostic.code(), 2591);
            assert_eq!(diagnostic.diagnostic.arguments, ["module"]);
            assert_eq!(node_text(&source, diagnostic.node.unwrap()), "module");
            assert_eq!(
                diagnostic.diagnostic.render().unwrap(),
                concat!(
                    "Cannot find name 'module'. Do you need to install type definitions ",
                    "for node? Try `npm i --save-dev @types/node` and then add 'node' ",
                    "to the types field in your tsconfig.",
                ),
            );
        }
        let mut ordered_diagnostics = diagnostics
            .iter()
            .map(|diagnostic| {
                (
                    source
                        .arena
                        .get(diagnostic.node.unwrap().node)
                        .unwrap()
                        .range
                        .start
                        .get(),
                    diagnostic.diagnostic.code(),
                )
            })
            .chain(source.diagnostics.iter().map(|diagnostic| {
                (
                    diagnostic.range.start.get(),
                    diagnostic.code.expect("anonymous-module parser diagnostic"),
                )
            }))
            .collect::<Vec<_>>();
        ordered_diagnostics.sort_unstable_by_key(|(position, _)| *position);
        assert_eq!(
            ordered_diagnostics
                .iter()
                .map(|(_, code)| *code)
                .collect::<Vec<_>>(),
            [2591, 1437, 2591, 1437, 2591, 1437],
        );

        let number = context.store().intrinsic_bootstrap().unwrap().number_type;
        for name in ["foo", "bar", "x"] {
            assert_eq!(variable_value_type(&context, &source, file, name), number);
        }
        let reads = identifier_expressions(&source, file, "bar");
        let [read] = reads.as_slice() else {
            panic!("expected one read of the shared bar symbol")
        };
        assert_eq!(resolved_node_type(&context, *read), number);
        assert_eq!(
            context
                .store()
                .symbol_node_links(*read)
                .and_then(|links| links.resolved_symbol),
            Some(variable_symbol(&context, &source, file, "bar")),
        );

        let warm = observable_state(&context, file);
        context.recheck_source_file(file).unwrap();
        assert_eq!(observable_state(&context, file), warm);
    }

