    #[test]
    fn value_augmentations_of_export_equals_variables_report_ts2649() {
        let library = parsed(concat!(
            "declare var callable: () => void; ",
            "declare namespace callable {} ",
            "export = callable;",
        ));
        let extension = parsed(concat!(
            "import * as callable from './library'; ",
            "declare module './library' { export function extra(): void; }",
        ));
        let library_file = FileId::new(8_356);
        let extension_file = FileId::new(8_357);
        let files = [(library_file, &library), (extension_file, &extension)];
        let mut binder = CanonicalBinder::new();
        for (file, parsed) in files {
            binder
                .bind_source_file_with_facts(
                    &parsed.arena,
                    parsed.source_file,
                    file,
                    CanonicalSourceFileFacts::new(
                        EscapedName::source(format!("\"/project/{}.d.ts\"", file.index())),
                        CanonicalSourceLanguage::TypeScript,
                        true,
                        CanonicalModuleState::External,
                    ),
                )
                .unwrap();
            binder
                .bind_typescript_declaration_slice(&parsed.arena, file)
                .unwrap();
        }
        let specifiers = source_module_specifiers(&extension);
        let [specifier] = specifiers.as_slice() else {
            panic!("the extension must retain one authenticated library import")
        };
        let manifest = CanonicalModuleResolutionManifestInput::new([
            CanonicalModuleResolutionEntry::resolved(
                NodeRef::new(extension.arena.id(), extension_file, *specifier),
                CanonicalResolvedModuleInput::new(
                    library_file,
                    CanonicalModuleResolutionMode::Esm,
                    CanonicalModuleResolutionMode::Esm,
                ),
            ),
        ]);
        let mut context = CanonicalCheckerContext::new_with_module_resolutions(
            binder.finish(),
            vec![
                (library_file, &library.arena),
                (extension_file, &extension.arena),
            ],
            CanonicalCheckerOptions::default(),
            manifest,
        )
        .unwrap();

        context.check_source_file(library_file).unwrap();
        context.check_source_file(extension_file).unwrap();

        let [diagnostic] = context.diagnostics().as_slice() else {
            panic!("expected one diagnostic for augmenting an exported non-module value")
        };
        assert_eq!(diagnostic.diagnostic.code(), 2649);
        assert_eq!(
            diagnostic.diagnostic.render().unwrap(),
            "Cannot augment module './library' with value exports because it resolves to a non-module entity.",
        );
        assert_eq!(
            node_text(&extension, diagnostic.node.unwrap()),
            "'./library'",
        );

        let warm = observable_state(&context, extension_file);
        context.recheck_source_file(extension_file).unwrap();
        assert_eq!(observable_state(&context, extension_file), warm);
    }

    #[test]
    fn namespace_imports_cross_authenticated_module_modes_without_changing_exports() {
        for (index, usage_mode, target_mode) in [
            (
                0,
                CanonicalModuleResolutionMode::Esm,
                CanonicalModuleResolutionMode::CommonJs,
            ),
            (
                1,
                CanonicalModuleResolutionMode::CommonJs,
                CanonicalModuleResolutionMode::Esm,
            ),
        ] {
            let source = parsed(concat!(
                "import * as values from './target'; ",
                "const result = values.value;",
            ));
            let target = parsed("export declare const value: number;");
            let source_file = FileId::new(8_370 + index * 2);
            let target_file = FileId::new(8_371 + index * 2);
            let files = [(source_file, &source, false), (target_file, &target, true)];
            let mut binder = CanonicalBinder::new();
            for (file, parsed, declaration_file) in files {
                binder
                    .bind_source_file_with_facts(
                        &parsed.arena,
                        parsed.source_file,
                        file,
                        CanonicalSourceFileFacts::new(
                            EscapedName::source(format!("\"/project/{}.ts\"", file.index())),
                            CanonicalSourceLanguage::TypeScript,
                            declaration_file,
                            CanonicalModuleState::External,
                        ),
                    )
                    .unwrap();
                binder
                    .bind_typescript_declaration_slice(&parsed.arena, file)
                    .unwrap();
            }
            let specifiers = source_module_specifiers(&source);
            let [specifier] = specifiers.as_slice() else {
                panic!("the namespace import must retain one exact module specifier")
            };
            let manifest = CanonicalModuleResolutionManifestInput::new([
                CanonicalModuleResolutionEntry::resolved(
                    NodeRef::new(source.arena.id(), source_file, *specifier),
                    CanonicalResolvedModuleInput::new(target_file, usage_mode, target_mode),
                ),
            ]);
            let mut context = CanonicalCheckerContext::new_with_module_resolutions(
                binder.finish(),
                vec![(source_file, &source.arena), (target_file, &target.arena)],
                CanonicalCheckerOptions::default(),
                manifest,
            )
            .unwrap();

            context.check_source_file(source_file).unwrap();

            let (_, target_bound) = context.file(target_file).unwrap();
            let target_module = target_bound.symbol(target_bound.source_file()).unwrap();
            let binding = source
                .arena
                .iter()
                .find_map(|(node, record)| {
                    (record.kind == SyntaxKind::NamespaceImport).then_some(NodeRef::new(
                        source.arena.id(),
                        source_file,
                        node,
                    ))
                })
                .unwrap();
            let (_, source_bound) = context.file(source_file).unwrap();
            let alias = source_bound.symbol(binding).unwrap();
            assert_eq!(
                context
                    .store()
                    .alias_symbol_links(alias)
                    .map(|links| (links.immediate_target, links.alias_target)),
                Some((
                    Some(target_module),
                    AliasTargetState::Resolved(target_module)
                )),
            );
            assert_eq!(
                variable_value_type(&context, &source, source_file, "result"),
                context.store().intrinsic_bootstrap().unwrap().number_type,
            );
            assert!(context.diagnostics().is_empty());
            let warm = observable_state(&context, source_file);

            context.recheck_source_file(source_file).unwrap();

            assert_eq!(observable_state(&context, source_file), warm);
        }
    }

    #[test]
    fn imported_callable_default_interface_returns_materialize_before_their_source() {
        let consumer = parsed(concat!(
            "import { styled } from './factory'; ",
            "export const value = styled();",
        ));
        let factory = parsed(concat!(
            "import Color from './color'; ",
            "export declare function styled(): Color;",
        ));
        let color = parsed("interface Color { c: string; } export default Color;");
        let consumer_file = FileId::new(8_340);
        let factory_file = FileId::new(8_341);
        let color_file = FileId::new(8_342);
        let files = [
            (consumer_file, &consumer),
            (factory_file, &factory),
            (color_file, &color),
        ];
        let mut context = external_context_with_import_routes(
            &files,
            &[
                SourceImportRoute {
                    source: 0,
                    specifier: 0,
                    target: 1,
                },
                SourceImportRoute {
                    source: 1,
                    specifier: 0,
                    target: 2,
                },
            ],
        );

        context.check_source_file(consumer_file).unwrap();
        assert!(!is_type_checked(&context, factory_file));
        assert!(!is_type_checked(&context, color_file));
        context.check_source_file(factory_file).unwrap();
        context.check_source_file(color_file).unwrap();
        assert!(context.diagnostics().is_empty());

        let interface = color
            .arena
            .iter()
            .find_map(|(node, record)| {
                (record.kind == SyntaxKind::InterfaceDeclaration).then_some(NodeRef::new(
                    color.arena.id(),
                    color_file,
                    node,
                ))
            })
            .unwrap();
        let (_, color_bound) = context.file(color_file).unwrap();
        let interface_symbol = color_bound.symbol(interface).unwrap();
        assert!(
            context
                .store()
                .value_symbol_links(interface_symbol)
                .is_none()
        );

        let warm = observable_state(&context, consumer_file);
        context.recheck_source_file(consumer_file).unwrap();
        assert_eq!(observable_state(&context, consumer_file), warm);
    }

