        context.check_source_file(file).unwrap();

        let diagnostics = context.diagnostics().as_slice();
        assert_eq!(diagnostics.len(), 1);
        assert_eq!(
            diagnostics[0].node,
            Some(variable_name(&source, file, "bad"))
        );
        assert_eq!(diagnostics[0].diagnostic.code(), 2322);
